<script setup>
import {ref,watch,onBeforeUnmount} from 'vue';import ActionIcon from './ActionIcon.vue';import {presets,preset,targetIcon,png} from '../action-art';
const props=defineProps({action:Object});const opened=ref(false),busy=ref(false),error=ref('');let revision=0,timer;
async function automatic(){const a=props.action,token=++revision,type=a.type,value=a.value,pluginId=a.pluginId;if(a.iconMode==='manual')return;busy.value=true;try{const result=await targetIcon(a);if(token===revision&&props.action===a&&a.iconMode!=='manual'&&a.type===type&&a.value===value&&a.pluginId===pluginId){a.image=result;a.icon=preset(a);a.iconMode='auto'}}catch{if(token===revision&&a.iconMode!=='manual'){a.image=presets[preset(a)].image;a.icon=preset(a)}}finally{if(token===revision)busy.value=false}}
watch(()=>[props.action,props.action.type,props.action.value,props.action.pluginId],(next,old)=>{clearTimeout(timer);revision++;if(old&&next[1]!==old[1]){props.action.iconMode='auto';delete props.action.image;delete props.action.icon}if(props.action.iconMode==='manual'||(!props.action.iconMode&&props.action.icon))return;if(!props.action.image)props.action.image=presets[preset(props.action)].image;timer=setTimeout(automatic,props.action.type==='url'?650:150)},{immediate:true});
function choose(id){clearTimeout(timer);revision++;busy.value=false;props.action.icon=id;props.action.image=presets[id].image;props.action.iconMode='manual';opened.value=false}
function reset(){props.action.iconMode='auto';delete props.action.icon;delete props.action.image;opened.value=false;void automatic()}
async function upload(){error.value='';try{const raw=await window.skk?.pickActionIcon?.();if(raw){clearTimeout(timer);revision++;props.action.image=await png(raw);props.action.iconMode='manual';opened.value=false}}catch(e){error.value=e.message}}
onBeforeUnmount(()=>{revision++;clearTimeout(timer)});
</script>
<template><div class="action-icon-picker"><button type="button" class="icon-picker-trigger" :aria-expanded="opened" aria-label="修改动作图标" @click="opened=!opened"><ActionIcon :action="action" :size="25"/><span>{{busy?'读取中…':'修改图标'}}</span></button><div v-if="opened" class="icon-picker-panel"><div class="icon-presets"><button v-for="(p,id) in presets" :key="id" type="button" :title="p.label" :aria-label="p.label" @click="choose(id)"><img :src="p.image" alt="" width="23" height="23"></button></div><div class="icon-picker-tools"><button type="button" @click="reset">自动图标</button><button type="button" @click="upload">选择图片</button><button type="button" @click="opened=false">关闭</button></div><small v-if="error" role="alert">{{error}}</small></div></div></template>
